import{z as s,x as i,o as e,c as A,q as t,j as r,D as E,d as o,s as B,S as l}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"YuLan","description":"","frontmatter":{"title":"YuLan","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/yulan.md","filePath":"llm/yulan.md","lastUpdated":1791063341000}'),p={name:"llm/yulan.md"};function d(h,a,m,u,D,L){const n=i("Mermaid");return e(),A("div",null,[a[2]||(a[2]=t('<h1 id="yulan" tabindex="-1">YuLan <a class="header-anchor" href="#yulan" aria-label="Permalink to &quot;YuLan&quot;">​</a></h1><div class="epigraph"><p>预训练约 1.7T token 分三阶段把能力铺开；指令微调与人类对齐都按由易到难的课程组织，长尾知识靠检测缺口再回灌语料，而不是再堆一轮随机网页。</p><footer>—— 人民大学高瓴人工智能学院，YuLan: An Open-source Large Language Model，arXiv:2406.19853</footer></div><p>玉兰是中国人民大学校花，也是高瓴人工智能学院（GSAI）开源大模型线的名字。2023 年 6 月起，团队先在 <a href="/llm/llama-1">LLaMA</a> / <a href="/llm/llama-2">LLaMA-2</a> 上做双语继续预训练与指令微调，放出 Chat-1（13B / 65B，delta 权重）与 Chat-2-13B；2024 年 7 月才交出<strong>从头训</strong>的 <strong>YuLan-Base-12B</strong> 与 <strong>YuLan-Chat-3-12B</strong>。本篇按 arXiv:2406.19853 写 12B 这条从零预训练报告：架构兼容 LLaMA 工具链、三阶段预训练、课程式 SFT 与课程式 <a href="/llm/rafailov-dpo">DPO</a>。更早的 LLaMA 差值权重、以及 2024 年底的 YuLan-Mini（2.42B，另文 2412.17743）只作谱系标注，不把 Mini 的合成长思维链写进 12B 贡献。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2023–2024 年开源中文模型大量是「英文底座 + 双语继续训」。继续训能补中文词表与语料，却继承原词表切字碎、上下文短、以及底座许可证对权重分发的约束。Chat-1 因此只发与官方检查点的差值；Chat-2 可以整包下载，但仍不是一份可复现的从零配方。报告要回答的是：在高校算力下，能否公开 <strong>12B 从零预训练</strong> 的数据构成、阶段划分与对齐课程，而不是只给聊天权重。</p><p>第二个问题是能力平台期。600B token 的标准下一词预测之后，MMLU 一类综合选择题仍接近随机：网页里很少出现「带解析的四选一」。再往后，指令微调会暴露长尾实体答不出——损失已经下降，但百科里的低频人物与制度缺口仍在。<span class="marginnote">术语翻译：长尾知识指的是语料里出现次数极少的实体——某位二三线历史人物、某条地方性法规。把所有实体按出现次数排序，头部少数明星词条被模型反复见到，而尾巴上绝大多数实体只出现过一两次，像长鞭的末梢，模型基本学不到。</span>这不是再随机混一批网页能自动补上的。</p><h3 id="兼容-llama-工具链-而不是新注意力" tabindex="-1">兼容 LLaMA 工具链，而不是新注意力 <a class="header-anchor" href="#兼容-llama-工具链-而不是新注意力" aria-label="Permalink to &quot;兼容 LLaMA 工具链，而不是新注意力&quot;">​</a></h3><p>结构明确跟 LLaMA：40 层解码器，注意力头 <strong>38</strong>，隐维 <strong>4864</strong>，FFN <strong>13056</strong>，合计约 12B。<a href="/llm/su-rope">RoPE</a>、<a href="/llm/swiglu">SwiGLU</a>、Pre-<a href="/llm/rmsnorm">RMSNorm</a>（\\(\\varepsilon=10^{-6}\\)）。词表在 LLaMA 英文子词上用 WordPiece 从中文预训练子集扩到 <strong>51,190</strong>，英文 token 保留，避免中文一字多片吃光 2K 窗口。Chat-3 上下文 <strong>4096</strong>。没有 GQA、没有 MoE：这是一份标准多头解码器，卖点在数据课程与对齐课程。</p><p><span class="marginnote">README 写「超过 1.6TB 词元」，论文摘要写大约 1.7T。阶段表是 600B + 900B + 180B。引用预训练规模时钉论文表，不要和磁盘上的 TB 混写成两个不同的训练量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练语料按源分成网页（OpenWebText2、C4、RefinedWeb、CC-100、自处理的 2021–2023 Common Crawl WET 等）、代码（The Stack、GitHub）、百科（Wikipedia 与百度百科）、论文（arXiv、peS2o）、问答（Stack Exchange、知乎）、书籍与教材、新闻、法律文书、专利、以及教育测评。语言配比与窗口按阶段变，而不是全程同一锅。</p><h3 id="三阶段预训练-标准、能力增强、长尾回灌" tabindex="-1">三阶段预训练：标准、能力增强、长尾回灌 <a class="header-anchor" href="#三阶段预训练-标准、能力增强、长尾回灌" aria-label="Permalink to &quot;三阶段预训练：标准、能力增强、长尾回灌&quot;">​</a></h3><p>阶段 1（标准预训练）：英:中:多语 \\(=76:22:2\\)，上下文 2048，<strong>600B</strong> token，学习率 \\(3\\times 10^{-4}\\) 余弦到 \\(3\\times 10^{-5}\\)，全局 batch 约 4M token。同源文本拼成长序列再切成等长样本，避免零填充。<span class="marginnote">数字实例：三阶段合计 \\(600+900+180=1680\\)B，约等于摘要里的 1.7T。其中阶段 2 的 900B 占了全程约 54%——「能力增强」不是收尾的小补丁，而是训练预算的主体：窗口翻倍到 4096、配比改成 90% 英文并灌入教育测评，都是在这最长的一段里完成的。</span>阶段 2（能力增强）：把窗口拉到 4096，配比改为 \\(90:10:0\\)，<strong>900B</strong>，学习率落到 \\(2\\times 10^{-5}\\) 平台；关键增量是<strong>教育测评</strong>——选择题格式与带解析的闭卷推理，用来打破 MMLU 平台期。阶段 3（长尾知识）：配比 \\(62:33:5\\)，仍 4096，<strong>180B</strong>。先用一小撮指令数据得到临时聊天模型，对百科实体合成问答、用评判模型打分，找出 \\(s_v\\) 低于阈值的实体；再用 TF-IDF 从预训练库检索相关段落回灌，迭代五轮。中文数据在此阶段几乎都走检索策略，英文约一半仍随机采样，以免把通用分布冲掉。</p><p>指令微调把已有指令集与合成多轮对话按复杂度分成简单 / 复杂两档，先简单后复杂。人类对齐用 <a href="/llm/rafailov-dpo">DPO</a>，但难度不是人工标死：用当前策略相对上一课程的奖励</p> \\[r = \\beta\\log\\frac{\\pi_\\theta(y_w\\mid p)}{\\pi_{\\theta_o}(y_w\\mid p)}-\\beta\\log\\frac{\\pi_\\theta(y_l\\mid p)}{\\pi_{\\theta_o}(y_l\\mid p)} \\]<p>低于阈值 \\(\\delta\\) 的样本留到下一轮，\\(\\delta\\) 逐步下降，形成由易到难的偏好课程。这与「一次 DPO 吃完所有偏好对」不同：难负例（隐晦攻击、细偏置）要等模型先能分开容易的正负。</p>',16)),(e(),r(l,null,{default:E(()=>[B(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%BD%91%E9%A1%B5%20%2F%20%E4%BB%A3%E7%A0%81%20%2F%20%E7%99%BE%E7%A7%91%20%2F%20%E6%B5%8B%E8%AF%84%22%5D%20--%3E%20S1%5B%22%E9%98%B6%E6%AE%B51%EF%BC%9A600B%20%40%202K%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E9%98%B6%E6%AE%B52%EF%BC%9A900B%20%40%204K%20%2B%20%E6%95%99%E8%82%B2%E6%B5%8B%E8%AF%84%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E9%98%B6%E6%AE%B53%EF%BC%9A180B%20%E9%95%BF%E5%B0%BE%E5%AE%9E%E4%BD%93%E5%9B%9E%E7%81%8C%22%5D%0A%20%20S3%20--%3E%20BASE%5B%22YuLan-Base-12B%22%5D%0A%20%20BASE%20--%3E%20SFT%5B%22%E8%AF%BE%E7%A8%8B%20SFT%EF%BC%9A%E7%AE%80%E5%8D%95%E2%86%92%E5%A4%8D%E6%9D%82%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22%E8%AF%BE%E7%A8%8B%20DPO%EF%BC%9A%E9%98%88%E5%80%BC%E9%80%92%E5%87%8F%22%5D%0A%20%20DPO%20--%3E%20CHAT%5B%22YuLan-Chat-3-12B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>扩词表的机制是压缩率：中文若被切成字节片，同样 4K 位置能装的语义更少，继续预训练也会把梯度浪费在拼字上。保留英文原词、只加中文词，是为了不破坏已有英文子词统计。三阶段预训练的机制则是<strong>分布调度</strong>：阶段 1 用网页把损失拉下来；阶段 2 用测评把「选择题 + 解析」这种预训练里稀缺的格式补进下一词预测；阶段 3 承认随机采样对长尾实体的覆盖是次线性的，必须先检测再检索。TF-IDF 不是新检索模型，它的作用是在 1.7T 库上可算——用稠密检索会另起一套索引工程。</p><h3 id="课程对齐只改变样本顺序-不改变损失形状" tabindex="-1">课程对齐只改变样本顺序，不改变损失形状 <a class="header-anchor" href="#课程对齐只改变样本顺序-不改变损失形状" aria-label="Permalink to &quot;课程对齐只改变样本顺序，不改变损失形状&quot;">​</a></h3><p>SFT 仍是条件语言建模，DPO 仍是那条 logistic 偏好损失。课程改变的是<strong>何时看见哪一类样本</strong>。复杂度阈值把多轮、长约束指令留到模型已经会跟单轮指令之后；DPO 的 \\(\\delta\\) 把「还分不开的对」留下来反复练。若把同一堆数据一次性打乱，报告认为长尾与难负例会被头部简单样本淹没。<span class="marginnote">常见误区：初学者容易以为「课程学习」是一种新的损失函数或新算法。实际上它只改「喂样本的顺序」：同一堆数据、同一条损失，先易后难地排。就像同一本习题册，按「先基础题后压轴题」的顺序做，和随机打乱做，学完的掌握度可以差很多。</span>这与 Aquila2 用 HeuriMentor 按下游指标改配比是同一类「训练期反馈」，只是 YuLan 的反馈发生在对齐阶段、用的是实体问答与 DPO 奖励，而不是预训练损失尖峰。</p><p>长尾回灌的循环是阶段 3 的核心机制：</p>',5)),(e(),r(l,null,{default:E(()=>[B(n,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20TMP%5B%22%E4%B8%B4%E6%97%B6%E8%81%8A%E5%A4%A9%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20GEN%5B%22%E5%AF%B9%E7%99%BE%E7%A7%91%E5%AE%9E%E4%BD%93%E5%90%88%E6%88%90%E9%97%AE%E7%AD%94%22%5D%0A%20%20GEN%20--%3E%20JUDGE%5B%22%E8%AF%84%E5%88%A4%E6%A8%A1%E5%9E%8B%E6%89%93%E5%88%86%20s_v%22%5D%0A%20%20JUDGE%20--%3E%20TH%7B%22s_v%20%E4%BD%8E%E4%BA%8E%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20TH%20--%3E%7C%22%E6%98%AF%3A%20%E7%BC%BA%E5%8F%A3%E5%AE%9E%E4%BD%93%22%7C%20RET%5B%22TF-IDF%20%E6%A3%80%E7%B4%A2%E7%9B%B8%E5%85%B3%E6%AE%B5%E8%90%BD%22%5D%0A%20%20TH%20--%3E%7C%22%E5%90%A6%22%7C%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E6%89%B9%E5%AE%9E%E4%BD%93%22%5D%0A%20%20RET%20--%3E%20FILL%5B%22%E6%AE%B5%E8%90%BD%E5%9B%9E%E7%81%8C%E8%AE%AD%E7%BB%83%E8%AF%AD%E6%96%99%22%5D%0A%20%20FILL%20--%3E%20TMP2%5B%22%E6%9B%B4%E6%96%B0%E6%A8%A1%E5%9E%8B%2C%20%E5%86%8D%E6%89%AB%E4%B8%80%E8%BD%AE%22%5D%0A%20%20TMP2%20-.-%3E%7C%22%E8%BF%AD%E4%BB%A3%E7%BA%A6%205%20%E8%BD%AE%22%7C%20GEN%0A%20%20FILL%20--%3E%20BASE%5B%22%E9%98%B6%E6%AE%B5%203%20%E8%AE%AD%E7%BB%83%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">Chat-1 基于 LLaMA 只发 delta，合并脚本见仓库 <code>apply_delta.py</code>。Chat-2 基于 LLaMA-2-13B，词表同样扩到 51,190，窗口到 8,192。不要把 Chat-2 的 8K 写成 Chat-3 的默认窗；12B 从零线的报告窗是 4K。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>12B 报告没有公开与工业 7B 同量级的 10T+ 数据，C-Eval / 高考子集上的优势来自双语与测评回灌，不宜外推成「12B 已经超过当时所有 13B」。阶段 3 用 ChatGPT 生成实体问、用 Baichuan-2-13B 做对错评判，长尾清单依赖这两套教师，复现成本不是「下个开源网页包」。DPO 课程的 \\(\\delta\\) 与复杂度公式以论文为准，开源 Chat 模板是 <code>[|Human|] / [|AI|]</code>，和 Vicuna 的 <code>USER:</code> 不是同一套。</p><p>许可：仓库标 MIT，但说明数据和代码仅供学术研究；基于 LLaMA 的一代还要叠加 Meta 许可。不要把 Chat-3 的 MIT 理解成训练数据可再分发。YuLan-Mini（2412.17743）是另一条 2.42B、1.08T 的数据效率实验：56 层、隐维 1920、GQA 30/6、退火到 28K，大量合成数据。它证明实验室规模也能把小模型打满同档，<strong>不是</strong> 12B 的蒸馏版，也不共享 12B 的三阶段配比。</p><p><span class="marginnote">YuLan-Chat-3 在仓库评测表上 C-Eval 约 50.5、MMLU 约 55.7，相对同表 LLaMA-2-13B 的中文分有抬升。这些是仓库协议下的数，不要和 OpenCompass 当时 Chat-2「第五」的快照混成一行。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>YuLan-12B 是人大高瓴从头预训练的开源解码器：40 层、隐维 4864、词表 51,190，约 1.7T token。</li><li>预训练三阶段：2K 标准混数 → 4K 能力增强（教育测评）→ 长尾实体检测与 TF-IDF 回灌。</li><li>对齐是课程 SFT 加课程 DPO，由易到难，而不是一次打乱偏好对。</li><li>Chat-1 / Chat-2 是 LLaMA 系继续训谱系；Mini 是 2.42B 另文，不要倒填进 2406.19853。</li><li>出处：YuLan Team，<em>YuLan: An Open-source Large Language Model</em>，arXiv:2406.19853；Mini 见 Huatong Song 等，arXiv:2412.17743。</li></ul>',7))])}const _=s(p,[["render",d]]);export{g as __pageData,_ as default};
